// ─── Auto-Healer Init ───
// Defines targets, pipeline configs, and test questions

const PIPELINES = {
  'TmgyRP20N4JFd9CB': {
    name: 'Standard',
    webhook: '/webhook/rag-multi-index-v3',
    targets: { finance: 90, btp: 85, juridique: 90, industrie: 85 }
  },
  'cjhEhVs0KV1ExHqX': {
    name: 'Quant',
    webhook: '/webhook/3e0f8010-39e0-4bca-9d19-35e5094391a9',
    targets: { finance: 95 }
  },
  '6257AfT1l4FMC6lY': {
    name: 'Graph',
    webhook: '/webhook/ff622742-6d71-4e91-af71-b5c666088717',
    targets: { finance: 75, btp: 70, juridique: 80, industrie: 70 }
  },
  'ALd4gOEqiKL5KR1p': {
    name: 'Orchestrator',
    webhook: '/webhook/orchestrator-v2',
    targets: { finance: 85, btp: 75, juridique: 80, industrie: 75 }
  }
};

// 20 smoke test questions (5 per sector) — must match actual Pinecone data
const SMOKE_TESTS = [
  { q: 'Quels sont les principaux ratios financiers pour évaluer la solvabilité ?', sector: 'finance', expected_keywords: ['ratio', 'solvabilité', 'dette', 'capitaux'] },
  { q: 'Comment fonctionne un crédit-bail immobilier ?', sector: 'finance', expected_keywords: ['crédit-bail', 'loyer', 'option', 'achat'] },
  { q: 'Quelles sont les normes IFRS pour la comptabilisation des revenus ?', sector: 'finance', expected_keywords: ['IFRS', 'revenu', 'comptabilisation', 'norme'] },
  { q: 'Comment calculer le besoin en fonds de roulement ?', sector: 'finance', expected_keywords: ['BFR', 'fonds', 'roulement', 'trésorerie'] },
  { q: 'Quelle est la différence entre marge brute et marge nette ?', sector: 'finance', expected_keywords: ['marge', 'brute', 'nette', 'résultat'] },
  { q: 'Quelles sont les étapes d\'un permis de construire ?', sector: 'btp', expected_keywords: ['permis', 'construire', 'mairie', 'délai'] },
  { q: 'Comment fonctionne le DTU 31.2 pour les maisons à ossature bois ?', sector: 'btp', expected_keywords: ['DTU', 'ossature', 'bois', 'construction'] },
  { q: 'Quelles sont les normes parasismiques en France ?', sector: 'btp', expected_keywords: ['parasismique', 'Eurocode', 'zone', 'sismique'] },
  { q: 'Comment rédiger un CCTP pour un marché public de travaux ?', sector: 'btp', expected_keywords: ['CCTP', 'marché', 'travaux', 'cahier'] },
  { q: 'Quelles sont les obligations de la RE2020 ?', sector: 'btp', expected_keywords: ['RE2020', 'énergie', 'carbone', 'bâtiment'] },
  { q: 'Quels sont les délais de prescription en droit civil français ?', sector: 'juridique', expected_keywords: ['prescription', 'délai', 'ans', 'civil'] },
  { q: 'Comment fonctionne la procédure de licenciement économique ?', sector: 'juridique', expected_keywords: ['licenciement', 'économique', 'procédure', 'salarié'] },
  { q: 'Quelles sont les obligations RGPD pour une PME ?', sector: 'juridique', expected_keywords: ['RGPD', 'données', 'personnelles', 'traitement'] },
  { q: 'Comment créer une SAS en France ?', sector: 'juridique', expected_keywords: ['SAS', 'statuts', 'capital', 'immatriculation'] },
  { q: 'Quelles sont les clauses essentielles d\'un contrat de travail ?', sector: 'juridique', expected_keywords: ['contrat', 'travail', 'clause', 'rémunération'] },
  { q: 'Comment mettre en place une démarche ISO 9001 ?', sector: 'industrie', expected_keywords: ['ISO', '9001', 'qualité', 'processus'] },
  { q: 'Quelles sont les étapes d\'une analyse AMDEC ?', sector: 'industrie', expected_keywords: ['AMDEC', 'défaillance', 'criticité', 'analyse'] },
  { q: 'Comment rédiger une fiche de données de sécurité ?', sector: 'industrie', expected_keywords: ['FDS', 'sécurité', 'données', 'substance'] },
  { q: 'Quels sont les principes du lean manufacturing ?', sector: 'industrie', expected_keywords: ['lean', 'gaspillage', 'flux', 'amélioration'] },
  { q: 'Comment planifier la maintenance préventive d\'équipements industriels ?', sector: 'industrie', expected_keywords: ['maintenance', 'préventive', 'équipement', 'planification'] }
];

const N8N_HOSTS = [
  'https://lbjlincoln-nomos-rag-engine.hf.space',
  'https://lbjlincoln-nomos-rag-engine-3.hf.space',
  'https://lbjlincoln-nomos-rag-engine-5.hf.space',
  'https://lbjlincoln-nomos-rag-engine-9.hf.space'
];

return [{
  json: {
    pipelines: PIPELINES,
    smoke_tests: SMOKE_TESTS,
    n8n_hosts: N8N_HOSTS,
    started_at: new Date().toISOString(),
    run_id: 'ah-' + Date.now()
  }
}];

// ─── Check Pipeline Health via Direct Webhook Pings ───
// Instead of fetching /rest/executions (requires cookie auth),
// we ping each pipeline webhook directly — more reliable.
const config = $input.first().json;
const hosts = config.n8n_hosts;
const results = [];

for (const [wfId, pipeline] of Object.entries(config.pipelines)) {
  let bestResult = null;

  for (const host of hosts) {
    try {
      const start = Date.now();
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: `${host}${pipeline.webhook}`,
        headers: { 'Content-Type': 'application/json' },
        body: { query: 'health check ping', tenant_id: 'healthcheck', top_k: 1 },
        timeout: 30000,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
      const elapsed = Date.now() - start;

      const hasResponse = resp.statusCode === 200;
      let responseOk = false;
      if (hasResponse) {
        const body = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body);
        responseOk = body.length > 20 && !body.includes('error');
      }

      bestResult = {
        pipeline: pipeline.name, workflow_id: wfId,
        host: host.split('//')[1].split('.')[0],
        status: responseOk ? 'HEALTHY' : hasResponse ? 'DEGRADED' : 'UNHEALTHY',
        http_status: resp.statusCode,
        response_ms: elapsed,
        response_ok: responseOk
      };
      if (responseOk) break; // Found a healthy host
    } catch (err) {
      continue;
    }
  }

  if (!bestResult) {
    results.push({ pipeline: pipeline.name, workflow_id: wfId, status: 'UNREACHABLE', error: 'All hosts timed out' });
  } else {
    results.push(bestResult);
  }
}

return [{ json: { ...config, execution_health: results,
  healthy_count: results.filter(r => r.status === 'HEALTHY').length,
  degraded_count: results.filter(r => r.status === 'DEGRADED').length,
  unhealthy_count: results.filter(r => r.status === 'UNHEALTHY' || r.status === 'UNREACHABLE').length
}}];

// ─── Run Smoke Tests (8 questions, round-robin across 4 hosts) ───
const config = $input.first().json;
const tests = config.smoke_tests;
const hosts = config.n8n_hosts;
const results = [];

// 2 questions per sector = 8 total, better coverage
const sectors = ['finance', 'btp', 'juridique', 'industrie'];
const selected = [];
for (const sector of sectors) {
  const sectorTests = tests.filter(t => t.sector === sector);
  // Shuffle and pick 2
  const shuffled = sectorTests.sort(() => Math.random() - 0.5);
  selected.push(shuffled[0]);
  if (shuffled.length > 1) selected.push(shuffled[1]);
}

for (let i = 0; i < selected.length; i++) {
  const test = selected[i];
  const host = hosts[i % hosts.length];
  const webhook = config.pipelines['TmgyRP20N4JFd9CB'].webhook;

  try {
    const start = Date.now();
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${host}${webhook}`,
      headers: { 'Content-Type': 'application/json' },
      body: { query: test.q, tenant_id: 'benchmark', top_k: 10, include_sources: true },
      timeout: 60000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
    const elapsed = Date.now() - start;

    let answer = '';
    if (resp.statusCode === 200) {
      const raw = typeof resp.body === 'string' ? JSON.parse(resp.body) : resp.body;
      answer = (raw.response || raw.answer || raw.result || JSON.stringify(raw)).toString().toLowerCase();
    }

    const matched = test.expected_keywords.filter(kw => answer.includes(kw.toLowerCase()));
    const score = matched.length / test.expected_keywords.length;

    results.push({
      sector: test.sector, question: test.q.substring(0, 80),
      status: resp.statusCode === 200 ? 'OK' : `HTTP_${resp.statusCode}`,
      response_time_ms: elapsed, keyword_score: Math.round(score * 100),
      matched_keywords: matched,
      missing_keywords: test.expected_keywords.filter(kw => !answer.includes(kw.toLowerCase())),
      answer_preview: answer.substring(0, 200),
      host: host.split('//')[1].split('.')[0]
    });
  } catch (err) {
    results.push({
      sector: test.sector, question: test.q.substring(0, 80),
      status: 'TIMEOUT', error: err.message, keyword_score: 0,
      host: host.split('//')[1].split('.')[0]
    });
  }
}

const sectorScores = {};
for (const r of results) {
  if (!sectorScores[r.sector]) sectorScores[r.sector] = [];
  sectorScores[r.sector].push(r.keyword_score);
}
const sectorAvg = {};
for (const [s, scores] of Object.entries(sectorScores)) {
  sectorAvg[s] = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
}

return [{ json: { ...config, smoke_results: results, sector_scores: sectorAvg,
  overall_score: Math.round(results.reduce((s, r) => s + r.keyword_score, 0) / results.length),
  avg_response_ms: Math.round(results.filter(r => r.response_time_ms).reduce((s, r) => s + r.response_time_ms, 0) / Math.max(results.filter(r => r.response_time_ms).length, 1)),
  timeouts: results.filter(r => r.status === 'TIMEOUT').length,
  errors: results.filter(r => r.status.startsWith('HTTP_')).length
}}];

// ─── Parse LLM response + Build structured report ───
const prev = $input.first().json;
let llmRaw = '';
let patch = null;
let parseError = null;

try {
  // Extract from HTTP response
  const choices = prev.choices || [];
  if (choices.length > 0) {
    llmRaw = choices[0].message?.content || '';
  }

  // Parse JSON from LLM
  if (llmRaw) {
    // Handle markdown code blocks
    let cleaned = llmRaw;
    if (cleaned.includes('```json')) {
      cleaned = cleaned.split('```json')[1].split('```')[0];
    } else if (cleaned.includes('```')) {
      cleaned = cleaned.split('```')[1].split('```')[0];
    }
    patch = JSON.parse(cleaned.trim());
  }
} catch (err) {
  parseError = `LLM parse error: ${err.message}. Raw: ${llmRaw.substring(0, 300)}`;
}

// Get smoke data from upstream (it's in the execution data chain)
const execData = $('Run Smoke Tests (5q)').first().json;

const report = {
  run_id: execData.run_id,
  timestamp: new Date().toISOString(),

  // Health summary
  execution_health: {
    healthy: execData.healthy_count,
    degraded: execData.degraded_count,
    unhealthy: execData.unhealthy_count,
    details: (execData.execution_health || []).map(h => ({
      pipeline: h.pipeline,
      status: h.status,
      success_rate: h.success_rate,
      avg_duration_ms: h.avg_duration_ms
    }))
  },

  // Smoke test results
  smoke_tests: {
    overall_score: execData.overall_score,
    sector_scores: execData.sector_scores,
    avg_response_ms: execData.avg_response_ms,
    timeouts: execData.timeouts,
    errors: execData.errors,
    details: (execData.smoke_results || []).map(r => ({
      sector: r.sector,
      score: r.keyword_score,
      status: r.status,
      response_ms: r.response_time_ms,
      missing_kw: r.missing_keywords
    }))
  },

  // LLM patch proposal
  patch_proposal: patch,
  patch_parse_error: parseError,

  // Decision: should Claude Code apply this?
  recommendation: !patch ? 'NO_PATCH' :
    patch.severity === 'CRITICAL' ? 'APPLY_URGENT' :
    patch.severity === 'HIGH' && patch.risk !== 'HIGH' ? 'APPLY_RECOMMENDED' :
    patch.severity === 'MEDIUM' ? 'APPLY_IF_IDLE' :
    'SKIP',

  // Targets comparison
  gaps: Object.entries(execData.sector_scores || {}).map(([sector, score]) => {
    const targets = { finance: 90, btp: 85, juridique: 90, industrie: 85 };
    return { sector, current: score, target: targets[sector] || 85, gap: (targets[sector] || 85) - score };
  }).sort((a, b) => b.gap - a.gap)
};

return [{ json: report }];

// ─── Format report for webhook delivery to Claude Code CLI ───
const report = $input.first().json;

// Compact format for the webhook POST
const payload = {
  type: 'auto-healer-report',
  version: '1.0',
  ...report
};

// Also generate human-readable summary
const lines = [
  `=== AUTO-HEALER REPORT ${report.run_id} ===${report.timestamp}`,
  '',
  `HEALTH: ${report.execution_health.healthy}H / ${report.execution_health.degraded}D / ${report.execution_health.unhealthy}U`,
  `SMOKE: ${report.smoke_tests.overall_score}% overall | Avg ${report.smoke_tests.avg_response_ms}ms | ${report.smoke_tests.timeouts} timeouts`,
  '',
  'SECTOR SCORES vs TARGETS:',
  ...(report.gaps || []).map(g => `  ${g.sector}: ${g.current}% / ${g.target}% (gap: ${g.gap}pp)`),
  '',
  `RECOMMENDATION: ${report.recommendation}`,
];

if (report.patch_proposal) {
  lines.push('');
  lines.push(`PATCH: [${report.patch_proposal.severity}] ${report.patch_proposal.target_pipeline} — ${report.patch_proposal.improvement_type}`);
  lines.push(`  Node: ${report.patch_proposal.specific_change?.node_name}`);
  lines.push(`  Change: ${report.patch_proposal.specific_change?.rationale}`);
  lines.push(`  Expected: ${report.patch_proposal.expected_impact}`);
  lines.push(`  Risk: ${report.patch_proposal.risk}`);
}

return [{
  json: {
    payload,
    summary: lines.join('\n')
  }
}];

// ─── Save report to persistent log ───
// This stores the report so Claude Code can fetch it via GET
const data = $input.first().json;

// Store in global static data for retrieval
const staticData = $getWorkflowStaticData('global');
if (!staticData.reports) staticData.reports = [];

// Keep last 50 reports
staticData.reports.unshift(data.payload);
if (staticData.reports.length > 50) staticData.reports = staticData.reports.slice(0, 50);
staticData.lastReport = data.payload;
staticData.lastUpdated = new Date().toISOString();

return [{ json: { stored: true, total_reports: staticData.reports.length, summary: data.summary } }];

// ─── Serve last report to Claude Code CLI ───
const staticData = $getWorkflowStaticData('global');
const last = staticData.lastReport || { error: 'No reports yet. Trigger the auto-healer first.' };
const count = (staticData.reports || []).length;

return [{
  json: {
    last_report: last,
    total_reports: count,
    last_updated: staticData.lastUpdated || null
  }
}];
